fn main(){let args:Vec<_>=std::env::args().collect();if args.len()!=4{panic!("Usage: semantic_benchmark <verified-model-pack-folder> <new-output-workspace> <max-notes>")}let result=noted_core::semantic::benchmark(std::path::Path::new(&args[1]),std::path::Path::new(&args[2]),args[3].parse().expect("note count")).expect("benchmark failed");println!("{}",serde_json::to_string_pretty(&result).unwrap());}
